const membersWithRoles = `-- name: MembersWithRoles :many
SELECT members.user_id,
    coalesce(array_agg(member_roles.role_id ORDER BY member_roles.role_id)
        FILTER (WHERE member_roles.role_id IS NOT NULL), '{}')::bigint[] AS role_ids
FROM members
LEFT JOIN member_roles ON member_roles.guild_id = members.guild_id AND member_roles.user_id = members.user_id
WHERE members.guild_id = $1
GROUP BY members.user_id
ORDER BY members.user_id
`

type MembersWithRolesRow struct {
	UserID  snowflake.ID
	RoleIds []int64
}

// Every member of the guild with the IDs of their non-@everyone roles.
func (q *Queries) MembersWithRoles(ctx context.Context, db DBTX, guildID snowflake.ID) ([]MembersWithRolesRow, error) {
	rows, err := db.Query(ctx, membersWithRoles, guildID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MembersWithRolesRow
	for rows.Next() {
		var i MembersWithRolesRow
		if err := rows.Scan(&i.UserID, &i.RoleIds); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const peerIDs = `-- name: PeerIDs :many
SELECT other.user_id FROM members AS mine
JOIN members AS other ON other.guild_id = mine.guild_id
WHERE mine.user_id = $1
UNION
SELECT rel.other_id FROM relationships AS rel WHERE rel.user_id = $1 AND rel.type = 1
ORDER BY user_id
`

// Everyone sharing a guild or a friendship with user_id, ascending.
func (q *Queries) PeerIDs(ctx context.Context, db DBTX, userID snowflake.ID) ([]snowflake.ID, error) {
	rows, err := db.Query(ctx, peerIDs, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []snowflake.ID
	for rows.Next() {
		var user_id snowflake.ID
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

