const replaceIconHash = `-- name: ReplaceIconHash :one
UPDATE guilds SET icon_hash = $1
FROM (SELECT guilds.icon_hash FROM guilds WHERE guilds.id = $2 FOR UPDATE) AS prev
WHERE guilds.id = $2
RETURNING guilds.id, guilds.name, guilds.icon_hash, guilds.owner_id, guilds.created_at, prev.icon_hash AS previous_hash
`

type ReplaceIconHashParams struct {
	IconHash *string
	ID       snowflake.ID
}

type ReplaceIconHashRow struct {
	Guild        Guild
	PreviousHash *string
}

// Locks the row first, so concurrent calls each see the hash they replace.
func (q *Queries) ReplaceIconHash(ctx context.Context, db DBTX, arg ReplaceIconHashParams) (ReplaceIconHashRow, error) {
	row := db.QueryRow(ctx, replaceIconHash, arg.IconHash, arg.ID)
	var i ReplaceIconHashRow
	err := row.Scan(
		&i.Guild.ID,
		&i.Guild.Name,
		&i.Guild.IconHash,
		&i.Guild.OwnerID,
		&i.Guild.CreatedAt,
		&i.PreviousHash,
	)
	return i, err
}

